// A recipient's inbox is filtered by database RLS and current operating-unit access.
async function loadNotifications(){S.notifications=[];S.notificationsReady=false;S.notificationsError='';if(!isStaff())return;try{S.notifications=await allRows('/rest/v1/occci_notifications?select=*&order=created_at.desc,id');S.notificationsReady=true;}catch(err){S.notificationsError=err.message;}}
function unreadNotificationCount(){return (S.notifications||[]).filter(n=>!n.read_at).length;}
function notificationBellMarkup(){if(!isStaff())return '';const count=unreadNotificationCount();return `<button type="button" class="icon-btn notification-button" onclick="go('Notifications')" aria-label="Notifications: ${count} unread" title="Notifications">${icon('bell')}<span class="portal-count ${count?'has-pending':''}">${count>99?'99+':count}</span></button>`;}
function notificationsView(){const unread=unreadNotificationCount();if(!S.notificationsReady)return heading('Notifications','Updates from your cooperative workspace.')+`<section class="card"><p class="form-error">${e(S.notificationsError||'Notifications need database activation.')}</p>${button('Retry','retryNotifications()','outline','switch')}</section>`;const rows=S.notifications.filter(n=>S.notificationFilter!=='unread'||!n.read_at),size=20,pages=Math.max(1,Math.ceil(rows.length/size));S.notificationPage=Math.min(pages,Math.max(1,S.notificationPage));const start=(S.notificationPage-1)*size;return heading('Notifications',`${unread} unread · Requests, decisions and activity within your access.`)+`<section class="card notifications-panel"><div class="notification-toolbar"><div class="tabs"><button type="button" class="${S.notificationFilter==='all'?'active':''}" onclick="S.notificationFilter='all';S.notificationPage=1;render()">All</button><button type="button" class="${S.notificationFilter==='unread'?'active':''}" onclick="S.notificationFilter='unread';S.notificationPage=1;render()">Unread</button></div><button type="button" class="outline small" onclick="markAllNotificationsRead(this)" ${unread?'':'disabled'}>Mark all as read</button></div><ul class="notification-list">${rows.slice(start,start+size).map(n=>`<li class="notification-row ${n.read_at?'':'is-unread'}"><button class="notification-open" type="button" onclick="openNotification('${n.id}',this)"><span class="notification-title">${e(n.title)}${n.read_at?'':'<span class="notification-unread-dot" aria-label="Unread"></span>'}</span><span class="notification-body">${e(n.body)}</span><small>${e(financeRecordedTime(n.created_at))}${n.scope_kind==='personal'?(n.target_type==='content'?' · Cooperative':' · Personal'):n.branch_id?' · '+e(bn(n.branch_id))+' branch':n.district?' · District '+e(n.district):' · Cooperative'}</small></button>${n.read_at?'':`<button class="outline small notification-read" type="button" onclick="markNotificationRead('${n.id}',this)" aria-label="Mark notification as read">${icon('check')}</button>`}</li>`).join('')}</ul>${rows.length?'':empty(S.notificationFilter==='unread'?'You are all caught up':'No notifications yet','Relevant requests, decisions and new activity will appear here.')}<nav class="pagination" aria-label="Notification pages"><span>${rows.length?start+1:0}–${Math.min(start+size,rows.length)} of ${rows.length} · 20 per page</span><div class="flex"><button type="button" class="outline small" onclick="S.notificationPage--;render()" ${S.notificationPage===1?'disabled':''}>Previous</button><span>Page ${S.notificationPage} of ${pages}</span><button type="button" class="outline small" onclick="S.notificationPage++;render()" ${S.notificationPage===pages?'disabled':''}>Next</button></div></nav></section>`;}
async function retryNotifications(){await loadNotifications();render();}
async function markNotificationRead(id,btn){if(btn)btn.disabled=true;try{await rpc('occci_mark_notifications_read',{notification_id:id});const n=S.notifications.find(n=>n.id===id);if(n)n.read_at=new Date().toISOString();if(typeof renderLiveChanges==='function')renderLiveChanges();else render();}catch(err){toast(err.message);}finally{if(btn)btn.disabled=false;}}
async function markAllNotificationsRead(btn){btn.disabled=true;try{await rpc('occci_mark_notifications_read',{notification_id:null});const now=new Date().toISOString();S.notifications.forEach(n=>n.read_at||=now);render();toast('Notifications marked as read.');}catch(err){toast(err.message);}finally{btn.disabled=false;}}
async function openNotification(id,btn){const n=S.notifications.find(n=>n.id===id);if(!n)return;if(btn)btn.disabled=true;try{await rpc('occci_mark_notifications_read',{notification_id:id});n.read_at||=new Date().toISOString();if(n.branch_id&&canReadBranch(n.branch_id))setOperatingBranch(n.branch_id);switch(n.target_type){case 'content':go('Content');break;case 'profile':if(!S.profiles.some(p=>p.id===n.target_id&&!p.archived_at&&canReadProfile(p)))throw Error('This record is no longer available in your workspace.');go('Members');memberDialog(n.target_id);break;case 'request':if(!S.requests.some(q=>q.id===n.target_id&&requestMember(q)))throw Error('This request is no longer available in your workspace.');go(S.requests.find(q=>q.id===n.target_id).kind==='Financial sync'?'Financial sync':S.requests.find(q=>q.id===n.target_id).kind==='Membership approval'?'New Members':'Approvals');requestDialog(n.target_id);break;case 'password_request':go('Password requests');if(S.role==='BM'&&S.passwordRequests.some(q=>q.id===n.target_id&&q.status==='Pending'))cashierPasswordReviewDialog(n.target_id);break;case 'staff_application':go('Team');S.teamTab='Applications';render();if(S.role==='Admin'&&S.applications.some(a=>a.user_id===n.target_id))staffApplicationDialog(n.target_id);break;case 'team':if(n.target_id===S.session.user.id)go('Profile');else{go('Team');if(S.profiles.some(p=>p.id===n.target_id&&canReadProfile(p)))memberDialog(n.target_id);}break;case 'payment':{const p=S.payments.find(p=>p.id===n.target_id&&canReadPayment(p));if(!p)throw Error('This receipt is no longer available in your workspace.');const receipts=S.payments.filter(r=>r.member_id===p.member_id&&canReadPayment(r));S.paymentPages['dialog:'+p.member_id]=Math.floor(receipts.findIndex(r=>r.id===p.id)/20)+1;go('Financial sync');memberPaymentsDialog(p.member_id);break;}case 'work_report':if(!S.workReports.some(r=>r.id===n.target_id))throw Error('This report is no longer available in your workspace.');go('Reports');S.reportTab='Work';render();workDialog(n.target_id);break;case 'report':if(!S.reports.some(r=>r.id===n.target_id))throw Error('This report is no longer available in your workspace.');go('Reports');reportDialog(n.target_id);break;default:{S.auditRole='all';S.auditSort='newest';const index=cmsAuditRows(S.audit).findIndex(a=>String(a.id)===String(n.target_id));if(index>=0)S.activityPages.activity=Math.floor(index/20)+1;go('Activity');if(index>=0){const detail=$('main').querySelectorAll('.activity-item')[index%20];if(detail){detail.open=true;detail.scrollIntoView?.({block:'nearest'});}}break;}}}catch(err){render();toast(err.message);}finally{if(btn)btn.disabled=false;}}
